// Strategy: Allocate a writable ia_lib_info_struct on the stack and pass its
// address to the API. After the call, if the library populated string pointers,
// touch a bounded amount of data to increase coverage while remaining safe.
{
    // Prepare a valid, writable output structure as required by the API.
    ia_lib_info_struct out_info;
    out_info.p_lib_name = (WORD8 *)0;
    out_info.p_version_num = (WORD8 *)0;

    // Invoke the target function with a properly sized/writable buffer.
    ixheaacd_get_lib_id_strings((pVOID)&out_info);

    // The API likely sets pointers to static strings. We must not free them.
    // Safely read a limited number of bytes to exercise consumer paths.
    // Limit each scan to 256 bytes to avoid excessive reads in case of malformed data.
    const int kMaxScan = 256;
    int seen = 0;

    if (out_info.p_lib_name) {
        // Bounded NUL-terminated scan
        const unsigned char *p = (const unsigned char *)out_info.p_lib_name;
        for (int i = 0; i < kMaxScan; ++i) {
            unsigned char c = p[i];
            seen ^= c; // accumulate to keep side-effect
            if (c == '\0') break;
        }
    }
    if (out_info.p_version_num) {
        const unsigned char *p = (const unsigned char *)out_info.p_version_num;
        for (int i = 0; i < kMaxScan; ++i) {
            unsigned char c = p[i];
            seen ^= (c << (i & 7));
            if (c == '\0') break;
        }
    }

    // Use the seen value in a benign way to prevent optimization removing reads.
    if ((seen & 0xFFFF0000) == 0xDEAD0000) {
        // Extremely unlikely; bail to mark an interesting path without asserting a property.
        FUZZ_BAIL();
    }

    // Validation summary:
    // - Provides a non-NULL, writable ia_lib_info_struct as required.
    // - Does not free or modify returned strings; only performs bounded reads for coverage.
}

